"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { BrandLogo } from "@/components/BrandLogo";
import {
  Building2,
  Plus,
  MapPin,
  Loader2,
  Trash2,
  LayoutGrid,
  ArrowLeft,
  Save,
  X,
} from "lucide-react";

interface VenueSection {
  id: string;
  name: string;
  seatCount: number;
}

interface Venue {
  id: string;
  name: string;
  location: string;
  sections: VenueSection[];
}

interface NewSection {
  name: string;
  rows: number;
  seatsPerRow: number;
}

export default function AdminVenuesPage() {
  const [venues, setVenues] = useState<Venue[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showCreateForm, setShowCreateForm] = useState(false);

  // Create form state
  const [newVenueName, setNewVenueName] = useState("");
  const [newVenueLocation, setNewVenueLocation] = useState("");
  const [newSections, setNewSections] = useState<NewSection[]>([
    { name: "VIP", rows: 3, seatsPerRow: 10 },
    { name: "Standard", rows: 5, seatsPerRow: 15 },
  ]);
  const [isCreating, setIsCreating] = useState(false);
  const [toast, setToast] = useState<{ message: string; type: "success" | "error" } | null>(null);

  useEffect(() => {
    fetchVenues();
  }, []);

  useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 5000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const fetchVenues = async () => {
    setIsLoading(true);
    try {
      const res = await fetch("/api/admin/venues");
      const data = await res.json();
      setVenues(data.venues || []);
    } catch {
      console.error("Failed to fetch venues");
    } finally {
      setIsLoading(false);
    }
  };

  const addSection = () => {
    setNewSections((prev) => [...prev, { name: "", rows: 5, seatsPerRow: 10 }]);
  };

  const removeSection = (index: number) => {
    setNewSections((prev) => prev.filter((_, i) => i !== index));
  };

  const updateSection = (index: number, field: keyof NewSection, value: string | number) => {
    setNewSections((prev) =>
      prev.map((s, i) => (i === index ? { ...s, [field]: value } : s))
    );
  };

  const handleCreate = async () => {
    if (!newVenueName.trim()) {
      setToast({ message: "Venue name is required.", type: "error" });
      return;
    }
    if (newSections.length === 0 || newSections.some((s) => !s.name.trim())) {
      setToast({ message: "All sections must have a name.", type: "error" });
      return;
    }

    setIsCreating(true);
    try {
      const res = await fetch("/api/admin/venues", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: newVenueName,
          location: newVenueLocation,
          sections: newSections,
        }),
      });

      if (res.ok) {
        setToast({ message: "Venue created successfully!", type: "success" });
        setShowCreateForm(false);
        setNewVenueName("");
        setNewVenueLocation("");
        setNewSections([
          { name: "VIP", rows: 3, seatsPerRow: 10 },
          { name: "Standard", rows: 5, seatsPerRow: 15 },
        ]);
        fetchVenues();
      } else {
        const data = await res.json();
        setToast({ message: data.error || "Failed to create venue.", type: "error" });
      }
    } catch {
      setToast({ message: "An unexpected error occurred.", type: "error" });
    } finally {
      setIsCreating(false);
    }
  };

  const totalSeats = (sections: NewSection[]) =>
    sections.reduce((sum, s) => sum + s.rows * s.seatsPerRow, 0);

  return (
    <div className="min-h-screen bg-[#050810] text-zinc-100 p-4 md:p-8 font-sans">
      <div className="max-w-5xl mx-auto">
        {/* Header */}
        <div className="mb-10">
          <Link
            href="/dashboard"
            className="inline-flex items-center gap-2 text-sm text-zinc-500 hover:text-white transition-colors mb-4"
          >
            <ArrowLeft className="w-4 h-4" /> Back to Dashboard
          </Link>
          <div className="flex justify-between items-center">
            <div>
              <BrandLogo compact />
              <h1 className="text-3xl font-bold text-white tracking-tight mt-2">Venue Management</h1>
              <p className="text-zinc-400 mt-1">Create and manage venues with seat layouts.</p>
            </div>
            <button
              type="button"
              onClick={() => setShowCreateForm(!showCreateForm)}
              className="px-5 py-2.5 bg-cyan-500 hover:bg-cyan-400 text-cyan-950 font-semibold rounded-xl flex items-center gap-2 transition-colors"
            >
              {showCreateForm ? <X className="w-5 h-5" /> : <Plus className="w-5 h-5" />}
              {showCreateForm ? "Cancel" : "Create Venue"}
            </button>
          </div>
        </div>

        {/* Create Form */}
        {showCreateForm && (
          <div className="bg-[#0c111d] border border-zinc-800 rounded-3xl p-8 shadow-2xl mb-8 space-y-6">
            <h2 className="text-xl font-semibold text-white">New Venue</h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label htmlFor="venue-name" className="text-sm font-medium text-zinc-400">
                  Venue Name
                </label>
                <input
                  id="venue-name"
                  type="text"
                  value={newVenueName}
                  onChange={(e) => setNewVenueName(e.target.value)}
                  className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-cyan-500 transition-colors"
                  placeholder="e.g. Grand Horizon IMAX"
                />
              </div>
              <div className="space-y-2">
                <label htmlFor="venue-location" className="text-sm font-medium text-zinc-400">
                  Location
                </label>
                <input
                  id="venue-location"
                  type="text"
                  value={newVenueLocation}
                  onChange={(e) => setNewVenueLocation(e.target.value)}
                  className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-cyan-500 transition-colors"
                  placeholder="e.g. New York"
                />
              </div>
            </div>

            {/* Sections */}
            <div>
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-medium text-white">Seat Sections</h3>
                <span className="text-sm text-cyan-400 font-medium">
                  {totalSeats(newSections)} total seats
                </span>
              </div>
              <div className="space-y-3">
                {newSections.map((section, idx) => (
                  <div
                    key={idx}
                    className="flex items-center gap-4 bg-zinc-900/50 border border-zinc-800 rounded-xl p-4"
                  >
                    <input
                      type="text"
                      value={section.name}
                      onChange={(e) => updateSection(idx, "name", e.target.value)}
                      className="flex-1 bg-zinc-900 border border-zinc-800 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-cyan-500 text-sm"
                      placeholder="Section name (e.g. VIP)"
                    />
                    <div className="flex items-center gap-2">
                      <label className="text-xs text-zinc-500 whitespace-nowrap">Rows</label>
                      <input
                        type="number"
                        min={1}
                        max={26}
                        value={section.rows}
                        onChange={(e) => updateSection(idx, "rows", parseInt(e.target.value) || 1)}
                        className="w-16 bg-zinc-900 border border-zinc-800 rounded-lg px-2 py-2 text-white text-center text-sm focus:outline-none focus:border-cyan-500"
                      />
                    </div>
                    <div className="flex items-center gap-2">
                      <label className="text-xs text-zinc-500 whitespace-nowrap">Seats/Row</label>
                      <input
                        type="number"
                        min={1}
                        max={50}
                        value={section.seatsPerRow}
                        onChange={(e) =>
                          updateSection(idx, "seatsPerRow", parseInt(e.target.value) || 1)
                        }
                        className="w-16 bg-zinc-900 border border-zinc-800 rounded-lg px-2 py-2 text-white text-center text-sm focus:outline-none focus:border-cyan-500"
                      />
                    </div>
                    <span className="text-xs text-zinc-500 w-16 text-right shrink-0">
                      {section.rows * section.seatsPerRow} seats
                    </span>
                    <button
                      type="button"
                      onClick={() => removeSection(idx)}
                      className="p-1 text-zinc-600 hover:text-red-400 transition-colors"
                      aria-label="Remove section"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                ))}
              </div>
              <button
                type="button"
                onClick={addSection}
                className="mt-3 text-sm text-cyan-400 hover:text-cyan-300 font-medium transition-colors"
              >
                + Add Section
              </button>
            </div>

            <div className="pt-4 border-t border-zinc-800">
              <button
                type="button"
                onClick={handleCreate}
                disabled={isCreating}
                className="px-6 py-3 bg-white text-black font-semibold rounded-xl flex items-center gap-2 transition-all hover:bg-zinc-200 disabled:opacity-50"
              >
                {isCreating ? (
                  <Loader2 className="w-5 h-5 animate-spin" />
                ) : (
                  <Save className="w-5 h-5" />
                )}
                Create Venue
              </button>
            </div>
          </div>
        )}

        {/* Venues List */}
        {isLoading && (
          <div className="flex flex-col items-center justify-center py-20">
            <Loader2 className="w-8 h-8 text-cyan-400 animate-spin mb-4" />
            <p className="text-zinc-500">Loading venues...</p>
          </div>
        )}

        {!isLoading && venues.length === 0 && !showCreateForm && (
          <div className="text-center py-20">
            <div className="w-20 h-20 bg-zinc-800/50 rounded-full flex items-center justify-center mx-auto mb-6">
              <Building2 className="w-8 h-8 text-zinc-600" />
            </div>
            <h2 className="text-xl font-semibold text-white mb-2">No venues configured</h2>
            <p className="text-zinc-500 mb-8">Create your first venue with a seat layout.</p>
          </div>
        )}

        {!isLoading && venues.length > 0 && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {venues.map((venue) => (
              <div
                key={venue.id}
                className="bg-[#0c111d] border border-zinc-800 rounded-2xl p-6 shadow-xl hover:border-zinc-700 transition-colors"
              >
                <div className="flex items-start justify-between mb-4">
                  <div>
                    <h3 className="text-lg font-bold text-white">{venue.name}</h3>
                    <p className="text-sm text-zinc-400 flex items-center gap-1.5 mt-1">
                      <MapPin className="w-3.5 h-3.5" />
                      {venue.location || "No location set"}
                    </p>
                  </div>
                  <div className="p-2 bg-zinc-900 rounded-lg border border-zinc-800">
                    <Building2 className="w-5 h-5 text-cyan-400" />
                  </div>
                </div>

                <div className="space-y-2">
                  {venue.sections.map((section) => (
                    <div
                      key={section.id}
                      className="flex items-center justify-between bg-zinc-900/50 border border-zinc-800/50 rounded-lg px-3 py-2"
                    >
                      <span className="text-sm font-medium text-zinc-300 flex items-center gap-2">
                        <LayoutGrid className="w-3.5 h-3.5 text-zinc-500" />
                        {section.name}
                      </span>
                      <span className="text-xs text-zinc-500">{section.seatCount} seats</span>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Toast */}
        <div
          className={`fixed bottom-8 left-1/2 -translate-x-1/2 transition-all duration-300 z-50 ${
            toast ? "translate-y-0 opacity-100" : "translate-y-8 opacity-0 pointer-events-none"
          }`}
        >
          {toast && (
            <div
              className={`px-6 py-4 rounded-xl shadow-2xl border flex items-center gap-3 backdrop-blur-md font-medium ${
                toast.type === "error"
                  ? "bg-red-500/10 border-red-500/50 text-red-200"
                  : "bg-emerald-500/10 border-emerald-500/50 text-emerald-200"
              }`}
            >
              {toast.message}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://placeholder.supabase.co';
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || 'placeholder';

// GET: List all venues with sections
export async function GET() {
  try {
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    if (supabaseUrl.includes('placeholder')) {
      return NextResponse.json({
        venues: [
          {
            id: 'aaaa1111-aaaa-1111-aaaa-1111aaaa1111',
            name: 'Grand Horizon IMAX Cinema',
            location: 'New York',
            sections: [
              { id: 'cccc3333-cccc-3333-cccc-3333cccc3333', name: 'VIP', seatCount: 2 },
              { id: 'dddd4444-dddd-4444-dddd-4444dddd4444', name: 'Standard', seatCount: 2 },
            ],
          },
          {
            id: 'bbbb2222-bbbb-2222-bbbb-2222bbbb2222',
            name: 'CyberDome Arena',
            location: 'London',
            sections: [
              { id: 'ffff6666-ffff-6666-ffff-6666ffff6666', name: 'Premium', seatCount: 2 },
            ],
          },
        ],
      });
    }

    const { data, error } = await supabase
      .from('venues')
      .select('id, name, location, venue_sections(id, name, seats(count))')
      .order('name');

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    const venues = (data || []).map((v: any) => ({
      id: v.id,
      name: v.name,
      location: v.location,
      sections: (v.venue_sections || []).map((s: any) => ({
        id: s.id,
        name: s.name,
        seatCount: s.seats?.[0]?.count ?? 0,
      })),
    }));

    return NextResponse.json({ venues });
  } catch (error: any) {
    console.error('Unhandled error in venues route:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

// POST: Create a new venue with sections and seats
export async function POST(request: Request) {
  try {
    const { name, location, sections } = await request.json();

    if (!name || !sections || sections.length === 0) {
      return NextResponse.json({ error: 'Missing venue name or sections' }, { status: 400 });
    }

    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    if (supabaseUrl.includes('placeholder')) {
      return NextResponse.json({ success: true, venueId: 'mock-venue-id' });
    }

    // 1. Create venue
    const { data: venueData, error: venueError } = await supabase
      .from('venues')
      .insert({ name, location: location || null })
      .select('id')
      .single();

    if (venueError) {
      return NextResponse.json({ error: venueError.message }, { status: 500 });
    }

    const venueId = venueData.id;

    // 2. Create sections and seats
    for (const section of sections) {
      const { data: sectionData, error: sectionError } = await supabase
        .from('venue_sections')
        .insert({ venue_id: venueId, name: section.name })
        .select('id')
        .single();

      if (sectionError) {
        console.error('Section creation error:', sectionError);
        continue;
      }

      const sectionId = sectionData.id;
      const rows = section.rows || 5;
      const seatsPerRow = section.seatsPerRow || 10;

      const seatsToInsert = [];
      for (let r = 0; r < rows; r++) {
        const rowLabel = String.fromCharCode(65 + r);
        for (let s = 1; s <= seatsPerRow; s++) {
          seatsToInsert.push({
            section_id: sectionId,
            row_identifier: rowLabel,
            seat_identifier: String(s),
          });
        }
      }

      if (seatsToInsert.length > 0) {
        const { error: seatsError } = await supabase.from('seats').insert(seatsToInsert);
        if (seatsError) {
          console.error('Seats creation error:', seatsError);
        }
      }
    }

    return NextResponse.json({ success: true, venueId });
  } catch (error: any) {
    console.error('Unhandled error in venue creation:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://placeholder.supabase.co';
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || 'placeholder';

export async function GET(
  request: Request,
  { params }: { params: Promise<{ ref: string }> }
) {
  try {
    const { ref } = await params;

    if (!ref) {
      return NextResponse.json({ error: 'Missing booking reference' }, { status: 400 });
    }

    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    // MOCK BYPASS
    if (supabaseUrl.includes('placeholder')) {
      return NextResponse.json({
        booking: {
          id: 'mock-booking-id',
          booking_ref: ref,
          total_amount: 170.00,
          status: 'confirmed',
          created_at: new Date().toISOString(),
          event_title: 'Hans Zimmer Live',
          venue_name: 'O2 Arena, London',
          show_date: 'Friday, Aug 21, 2026',
          show_time: '20:00',
          seats: [
            { row: 'A', number: '12', category: 'VIP', price: 150.00 },
          ],
          qr_code_url: null,
        },
      });
    }

    const { data, error } = await supabase
      .from('bookings')
      .select(`
        id,
        booking_ref,
        total_amount,
        status,
        created_at,
        qr_code_url,
        shows (
          start_time,
          end_time,
          events (title),
          venues (name, location)
        ),
        booking_items (
          price,
          show_seats (
            seats (
              row_identifier,
              seat_identifier,
              venue_sections (name)
            )
          )
        )
      `)
      .eq('booking_ref', ref)
      .single();

    if (error || !data) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 });
    }

    const showsObj = Array.isArray(data.shows) ? data.shows[0] : data.shows;
    const startTime = (showsObj as any)?.start_time;

    const showDate = startTime
      ? new Date(startTime).toLocaleDateString('en-US', {
          weekday: 'long',
          month: 'short',
          day: 'numeric',
          year: 'numeric',
        })
      : 'Unknown Date';

    const showTime = startTime
      ? new Date(startTime).toLocaleTimeString('en-US', {
          hour: '2-digit',
          minute: '2-digit',
          hour12: false,
        })
      : 'Unknown Time';

    const booking = {
      id: data.id,
      booking_ref: data.booking_ref,
      total_amount: data.total_amount,
      status: data.status,
      created_at: data.created_at,
      event_title: (showsObj as any)?.events?.title ?? 'Unknown Event',
      venue_name: `${(showsObj as any)?.venues?.name ?? 'Unknown'}, ${(showsObj as any)?.venues?.location ?? ''}`.trim(),
      show_date: showDate,
      show_time: showTime,
      qr_code_url: data.qr_code_url,
      seats: ((data as any).booking_items || []).map((item: any) => ({
        row: item.show_seats?.seats?.row_identifier ?? '?',
        number: item.show_seats?.seats?.seat_identifier ?? '?',
        category: item.show_seats?.seats?.venue_sections?.name ?? 'Standard',
        price: item.price,
      })),
    };

    return NextResponse.json({ booking });
  } catch (error: any) {
    console.error('Unhandled error in booking detail route:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';
import { sendEmail } from '@/lib/email';
import { WaitlistOfferEmail } from '@/components/emails/WaitlistOfferEmail';
import React from 'react';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://placeholder.supabase.co';
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || 'placeholder';

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { bookingId, userId } = body;

    if (!bookingId || !userId) {
      return NextResponse.json({ error: 'Missing bookingId or userId' }, { status: 400 });
    }

    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    // MOCK BYPASS FOR LOCAL TESTING
    if (supabaseUrl.includes('placeholder')) {
      return NextResponse.json({
        success: true,
        message: 'Booking cancelled (mock mode). Waitlist reallocation simulated.',
        reallocations: [],
      });
    }

    // Call the correct RPC: cancel_booking_and_reallocate
    const { data: result, error } = await supabase.rpc('cancel_booking_and_reallocate', {
      p_booking_id: bookingId,
      p_user_id: userId,
    });

    if (error) {
      console.error('Error cancelling booking:', error);
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    // After cancellation, check if any waitlist entries were moved to 'offered' status
    // and send email notifications to those users
    const { data: offeredEntries } = await supabase
      .from('waitlist')
      .select(`
        id,
        user_id,
        offered_seat_id,
        offer_expires_at,
        show_id,
        section_id,
        profiles (email),
        show_seats (
          price,
          seats (
            row_identifier,
            seat_identifier,
            venue_sections (name)
          )
        ),
        shows (
          events (title),
          venues (name, location)
        )
      `)
      .eq('status', 'offered')
      .not('offer_expires_at', 'is', null)
      .gte('offer_expires_at', new Date().toISOString());

    if (offeredEntries && offeredEntries.length > 0) {
      for (const entry of offeredEntries) {
        const userEmail = (entry as any).profiles?.email;
        if (!userEmail) continue;

        const offerToken = entry.id; // Use waitlist ID as the claim token
        const claimUrl = `${process.env.NEXT_PUBLIC_SITE_URL || 'http://localhost:3000'}/checkout/claim?token=${offerToken}`;
        const eventTitle = (entry as any).shows?.events?.title ?? 'Event';
        const venueName = `${(entry as any).shows?.venues?.name ?? 'Venue'}, ${(entry as any).shows?.venues?.location ?? ''}`.trim();
        const seatCategory = (entry as any).show_seats?.seats?.venue_sections?.name ?? 'Standard';
        const seatRow = (entry as any).show_seats?.seats?.row_identifier ?? '?';
        const seatNumber = (entry as any).show_seats?.seats?.seat_identifier ?? '?';
        const price = Number((entry as any).show_seats?.price ?? 0);

        try {
          await sendEmail({
            to: userEmail,
            subject: `🎫 A seat just opened up for ${eventTitle}!`,
