      } catch {
        // Use fallback venues
        setVenues([
          { id: 'aaaa1111-aaaa-1111-aaaa-1111aaaa1111', name: 'Grand Horizon IMAX Cinema', location: 'New York' },
          { id: 'bbbb2222-bbbb-2222-bbbb-2222bbbb2222', name: 'CyberDome Arena', location: 'London' },
